"""Direct live resource/queue refresh, exact independent production checkpoint replay then win."""
import argparse,asyncio,datetime,json
from playwright.async_api import async_playwright
from test_expedition_browser import ROOT,KEY,FIELDS,snap,load,watch,Pilot,begin,complete,command,until
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url};pilot=await Pilot().start()
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1100});p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,args.url);await begin(p);await command(p,{'kind':'order','ids':['p1'],'order':{'kind':'gather','target':'south'}});s=await snap(p);await command(p,{'kind':'buy','type':'ranger','token':s['nextToken'],'revision':s['revision']});before=await until(p,lambda s:any(u['carry']>0 for u in s['units']) and bool(s['queue']));assert before['state']=='playing';await load(p,args.url,True);after=await snap(p);cp=await p.evaluate('JSON.parse(localStorage.getItem('+json.dumps(KEY)+')).resume');assert after['state']=='paused' and after['ui']['pending'] is None
   source="import fs from 'node:fs';import{restore,snapshot}from './games/expedition/engine.mjs';console.log(JSON.stringify(snapshot(restore(JSON.parse(fs.readFileSync(0,'utf8'))))))";proc=await asyncio.create_subprocess_exec('node','--input-type=module','-e',source,cwd=str(ROOT),stdin=asyncio.subprocess.PIPE,stdout=asyncio.subprocess.PIPE,stderr=asyncio.subprocess.PIPE);stdout,stderr=await proc.communicate(json.dumps(cp).encode());assert proc.returncode==0,stderr.decode();expected=json.loads(stdout);assert all(after[k]==expected[k] for k in FIELDS);await p.wait_for_timeout(500);waited=await snap(p);assert all(waited[k]==after[k] for k in FIELDS);await p.locator('#resume').click();end,_,_=await complete(p,pilot);assert end['state']=='won' and end['home']['hp']>0;assert not errors and not bad and not failed;report.update(passed=True,method='Real gather and paid production, direct reload during live carried resource/queue with no manual pause. Pagehide may record later legitimate ticks. Independent Node production restore of persisted legal checkpoint matches all22fields; then normal controls win. No browser state writes.',beforeRefresh={k:before[k] for k in FIELDS},savedCheckpoint=cp,restored={k:after[k] for k in FIELDS},exactFields=FIELDS,continuedWin={'stock':end['stock'],'homeHP':end['home']['hp'],'stats':end['stats'],'actualLog':end['log']});await ctx.close();print(json.dumps({'passed':True,'beforeTick':before['ticks'],'savedTick':cp['ticks'],'winStock':end['stock']}))
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1400];raise
  finally:report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8');await b.close();await pilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/games/expedition/');a.add_argument('--out',default='docs/expedition-qa/public-refresh.json');asyncio.run(main(a.parse_args()))
